// Dependency-free smoke checks; JUnit tests remain the canonical test suite.
import id.dompetdeadline.model.*;import id.dompetdeadline.service.*;
import java.time.*;import java.nio.file.*;import java.io.*;import java.util.*;
public class OfflineSmoke {
 static int checks=0;
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);checks++;System.out.println("PASS "+message);}
 public static void main(String[] args)throws Exception{LocalDate date=LocalDate.of(2026,11,26);LocalDateTime now=date.atTime(8,0);YearMonth m=YearMonth.from(date);Tugas t=new Tugas(1,"Laporan","PBO",now.plusHours(24),"Tinggi",false);Data d=new Data(List.of(new Kategori(1,"Uang saku","Pemasukan"),new Kategori(2,"Kuliah","Pengeluaran")),List.of(t),List.of(new Transaksi(1,date,100000,1,null,""),new Transaksi(2,date,25000,2,1L,"Cetak, \"laporan\"\nPBO"),new Transaksi(3,date.minusMonths(1),5000,2,1L,"")),List.of());check(Finance.balance(d,m)==75000,"monthly balance");check(Finance.cost(d,1)==30000,"linked expense all months");check(Finance.activeCost(d)==30000,"active task cost");check(Finance.urgent(t,now),"24-hour boundary");check(!Finance.urgent(t,now.minusMinutes(1)),"outside reminder window");check(!Finance.urgent(t,now.plusHours(25)),"past deadline");check(Finance.upcoming(d,3).size()==1,"upcoming tasks");check(Finance.byCategory(d,m).get("Kuliah")==25000L,"category chart");check(Finance.budgetStatus(79,100).equals("Aman"),"budget below threshold");check(Finance.budgetStatus(80,100).equals("Hampir habis"),"budget warning");check(Finance.budgetStatus(100,100).equals("Batas tercapai"),"budget exceeded");try{Finance.amount("12.500");throw new AssertionError("validation");}catch(IllegalArgumentException e){check(true,"money validation");}Path path=Files.createTempFile("dompet-", ".csv");try{Csv.exportFile(path,d);List<Transaksi> x=Csv.importFile(path,d);check(x.size()==3,"CSV transaction count");check(x.get(1).catatan.equals(d.transaksi.get(1).catatan),"CSV escaped comma, quote and newline");check(x.get(1).tugasId==1L,"CSV task link");check(Csv.parse(new StringReader("\uFEFF\"x\",y\r\n")).get(0).get(0).equals("x"),"CSV UTF-8 BOM");}finally{Files.deleteIfExists(path);}System.out.println("Total: "+checks+" checks passed.");}
}
